4}.choices-label{font-size:9px;text-transform:uppercase;letter-spacing:.16em;font-weight:700;color:#929087;margin:28px 0 11px}.choice-list{display:grid;gap:9px}.choice{position:relative;text-align:left;width:100%;border:1px solid #e7e0d7;background:#fffefa;color:var(--ink);padding:14px 45px 14px 16px;border-radius:3px;cursor:pointer;transition:.17s}.choice:hover{border-color:#d49b83;background:#fdf8f3;transform:translateX(3px)}.choice:after{content:'↗';position:absolute;right:17px;top:50%;transform:translateY(-50%);color:var(--coral);font-size:15px}.choice strong{display:block;font-size:12px;font-weight:600}.choice small{display:block;font-size:10px;color:#85847c;line-height:1.55;margin-top:5px}.toast{margin-top:15px;color:#876b5a;font-size:11px;line-height:1.55;animation:rise .25s ease both}.story-nav{display:flex;justify-content:space-between;align-items:center;margin-top:22px}.quiet-link{font-size:10px;color:#77776f;text-decoration:underline;text-underline-offset:3px;background:none;border:0;cursor:pointer;padding:8px 0}.cast-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:11px;margin-top:24px}.person-card{border:1px solid var(--line);padding:17px;text-align:left;background:#fffefa;border-radius:4px;cursor:pointer;transition:.18s;color:var(--ink)}.person-card:hover{border-color:#d49b83;transform:translateY(-2px);box-shadow:0 8px 18px #44362a0d}.person-card .avatar{margin-bottom:12px;height:43px;width:43px}.person-card strong{display:block;font-family:var(--serif);font-size:21px;font-weight:500}.person-card .person-meta{font-size:10px;color:#8c887f;margin-top:4px}.person-card p{font-size:11px;line-height:1.6;color:#6d6f67;margin:10px 0 0}.person-card .meet{margin-top:13px;font-size:9px;text-transform:uppercase;letter-spacing:.12em;color:var(--coral-dark);font-weight:700}.tag{display:inline-block;font-size:9px;padding:5px 8px;background:#f3eee6;color:#77746c;border-radius:20px;margin:3px 3px 0 0}
.ending-card{text-align:center;padding:clamp(30px,6vw,66px);position:relative;overflow:hidden}.ending-card:before{content:'✳';position:absolute;color:#f4ede3;opacity:.65;font-size:250px;top:-90px;right:-30px;pointer-events:none}.ending-card>*{position:relative}.ending-icon{font-size:37px;color:var(--coral);margin:2px 0 16px}.ending-title{font-size:clamp(35px,5vw,56px);max-width:590px;margin:12px auto 17px;line-height:1.08}.ending-copy{font-size:14px;line-height:1.9;color:#696a63;max-width:610px;margin:0 auto 15px;white-space:pre-line}.ending-meta{font-size:10px;letter-spacing:.1em;text-transform:uppercase;color:#9b7869;margin:21px 0 28px}.ending-actions{display:flex;justify-content:center;gap:12px;flex-wrap:wrap}.secondary-button{padding:14px 19px;border:1px solid var(--line);background:transparent;color:var(--ink);font-size:11px;border-radius:3px;font-weight:600}.secondary-button:hover{background:#f5eee6}.collection{margin-top:24px;padding-top:20px;border-top:1px solid var(--line);text-align:left}.collection h3{font-family:var(--serif);font-size:19px;font-weight:500}.ending-count{color:var(--coral-dark);font-weight:700}
@media(max-width:760px){.app-shell{width:min(100% - 30px,620px)}.topbar{height:68px}.chapter-label{display:none}.hero{grid-template-columns:1fr;gap:28px;padding:43px 0;min-height:auto}.hero h1{font-size:clamp(55px,14vw,76px)}.poster{height:350px;width:min(100%,390px);justify-self:center;border-radius:47% 47% 5px 5px/38% 38% 5px 5px}.poster-sun{width:103px;height:103px;top:48px;left:calc(50% - 52px)}.poster-window{height:168px;width:132px}.poster-silhouette{height:72px;width:46px}.poster-silhouette:before{top:-29px;left:12px;width:26px;height:33px}.poster-caption{font-size:17px}.panel{margin:35px auto 45px}.story-layout{grid-template-columns:1fr;margin:24px auto 40px;gap:12px}.side-card{position:static;padding:13px 15px;display:grid;grid-template-columns:1fr auto;align-items:center;gap:0 12px}.side-eyebrow{grid-column:1}.day-count{grid-column:1;margin:2px 0 0;font-size:24px}.side-caption{grid-column:1;margin:0}.progress-track{grid-column:2;grid-row:1;width:90px;margin:0}.route-mini,.stat-list{display:none}.story-card{min-height:0}.cast-grid{grid-template-columns:1fr 1fr}.person-card{padding:14px}.person-card strong{font-size:19px}.site-footer{font-size:8px}.site-footer span:last-child{font-size:10px;text-align:right}}
@media(max-width:440px){.app-shell{width:calc(100% - 24px)}.wordmark{font-size:12px}.topbar-right{gap:10px}.form-grid{grid-template-columns:1fr}.field.full{grid-column:auto}.form-footer{align-items:flex-start;flex-direction:column-reverse}.form-footer .primary-button{width:100%}.cast-grid{grid-template-columns:1fr}.person-card{display:grid;grid-template-columns:48px 1fr;column-gap:11px;align-items:center}.person-card .avatar{grid-row:span 3;margin:0}.person-card p,.person-card .meet{grid-column:2}.person-card p{margin-top:6px}.story-card{padding:22px 18px}.scene-copy{font-size:13px}.dialogue{font-size:15px}.site-footer{gap:10px}.poster{height:320px}}
