const defaults=()=>({screen:'home',profile:null,route:null,scene:0,stats:{warmth:0,trust:0,spark:0,honesty:0},path:[],feedback:null,ending:null});
let state=load();let sound=false;
function load(){try{return JSON.parse(localStorage.getItem(SAVE))||defaults()}catch{return defaults()}}
function persist(){try{localStorage.setItem(SAVE,JSON.stringify(state))}catch{}}
function collection(){try{return JSON.parse(localStorage.getItem(COLL)||'[]')}catch{return[]}}
function safe(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function setHeader(text){caption.textContent=text}
function btn(text,fn,cls='primary-button'){return `<button class="${cls}" data-action="${fn}">${text}</button>`}
function render(){persist();if(state.screen==='home')home();else if(state.screen==='setup')setup();else if(state.screen==='cast')showCast();else if(state.screen==='story')story();else if(state.screen==='ending')ending()}
function home(){setHeader('A story about finding your people');const saved=state.profile&&['cast','story','ending'].includes(state.screen);app.innerHTML=`<div class="hero"><div><div class="eyebrow">A choice-driven dating story</div><h1>All the<br>little <em>lights.</em></h1><p class="hero-copy">One festival. Six strangers with their own stories. A hundred small ways to show up—and more than 600 possible endings to discover.</p><div class="hero-actions">${btn('Begin your story&nbsp; →','new-game')}${saved?btn('Continue where you left off →','continue','text-button'):''}</div><p class="hero-note">A gentle, inclusive story about connection. No wrong answers. Everyone you meet is 21+.</p></div><div class="poster" aria-label="Illustration of a warm-lit window at sunset"><div class="poster-sun"></div><span class="poster-star s1">✦</span><span class="poster-star s2">✧</span><span class="poster-star s3">✦</span><div class="poster-hill hill-back"></div><div class="poster-hill hill-front"></div><div class="poster-window"></div><div class="poster-silhouette"></div><div class="poster-lamp">✦</div><div class="poster-caption">Somewhere, someone is glad you came.<small>Welcome to Bellwether</small></div></div></div>`}
