function side(){const r=state.route;const n=state.scene;const labels=['First hello','Getting closer','A little honesty','The last lantern'];return `<aside class="side-card"><div class="side-eyebrow">Bellwether festival</div><div class="day-count">${n<4?`Night ${n+1}`:'The last night'}</div><p class="side-caption">${n<4?labels[n]:'Your story, your way'}</p><div class="progress-track"><div class="progress-fill" style="width:${Math.min(100,n/4*100)}%"></div></div><div class="route-mini"><span class="avatar" style="background:${r.color}">${r.icon}</span><div><strong>${r.name}</strong><span>${r.role}</span></div></div><div class="stat-list">${[['warmth','Warmth'],['trust','Trust'],['spark','Spark'],['honesty','Honesty']].map(([k,l])=>`<div class="stat-row"><span>${l}</span>${dots(state.stats[k])}</div>`).join('')}</div></aside>`}
function story(){const r=state.route;if(!r){state.screen='cast';return showCast()}setHeader(`${r.name} · ${r.role}`);const final=state.scene>=r.scenes.length;const s=final?null:r.scenes[state.scene];let body='';if(state.feedback){body=`<div class="dialogue">${safe(state.feedback)}</div>${btn('Stay a little longer&nbsp; →','next-scene')}<div class="story-nav"><button class="quiet-link" data-action="cast">Meet someone else</button><span class="field-hint">Your choices are saved automatically.</span></div>`}else if(final){body=`<p class="scene-copy">The festival is winding down. Lanterns drift over the rooftops, carrying the small moments you shared into the night. What feels right to you?</p><div class="choices-label">Choose the shape of your ending</div><div class="choice-list"><button class="choice" data-ending="romance"><strong>Tell ${r.name} you want to explore this together</strong><small>Open the door to a romance, at a pace you define.</small></button><button class="choice" data-ending="friendship"><strong>Ask if you can keep this as a friendship</strong><small>Choose the connection without making it romantic.</small></button><button class="choice" data-ending="self"><strong>Thank them, then follow your own light</strong><small>Leave the festival with yourself as your next great love.</small></button></div><div class="story-nav"><button class="quiet-link" data-action="cast">Meet someone else instead</button><span class="field-hint">There is no bad ending here.</span></div>`}else{body=`<div class="scene-meta"><span class="scene-location">${s[0]}</span><span class="scene-day">NIGHT ${state.scene+1} OF 4</span></div><h2 class="scene-title">${s[1]}</h2><p class="scene-copy">${s[2]}</p><div class="dialogue">${s[3]}</div><div class="choices-label">How do you respond?</div><div class="choice-list">${s[4].map((c,i)=>`<button class="choice" data-choice="${i}"><strong>${c[0]}</strong><small>${c[1]}</small></button>`).join('')}</div><div class="story-nav"><button class="quiet-link" data-action="cast">Meet someone else</button><span class="field-hint">There are no wrong answers.</span></div>`}app.innerHTML=`<div class="story-layout">${side()}<article class="story-card">${!state.feedback&&!final?`<div class="scene-meta"><span class="scene-location">${s[0]}</span><span class="scene-day">NIGHT ${state.scene+1} OF 4</span></div><h2 class="scene-title">${s[1]}</h2><p class="scene-copy">${s[2]}</p><div class="dialogue">${s[3]}</div><div class="choices-label">How do you respond?</div><div class="choice-list">${s[4].map((c,i)=>`<button class="choice" data-choice="${i}"><strong>${c[0]}</strong><small>${c[1]}</small></button>`).join('')}</div><div class="story-nav"><button class="quiet-link" data-action="cast">Meet someone else</button><span class="field-hint">There are no wrong answers.</span></div>`:final&&!state.feedback?body:body}</article></div>`}
function choose(index){const s=state.route.scenes[state.scene],c=s&&s[4][index];if(!c)return;for(const [k,v] of Object.entries(c[3]))state.stats[k]+=v;state.path.push({choice:index,mood:c[4]});state.feedback=c[2];render()}
function nextScene(){state.feedback=null;state.scene++;render()}
function finish(type){const score=Object.values(state.stats).reduce((a,b)=>a+b,0);const tier=score<6?'tender':score<9?'bright':'deep';const rank={tender:0,bright:1,deep:2};const top=Math.max(...Object.values(state.stats));const keys=['warmth','trust','spark','honesty'];const motif=keys.find(k=>state.stats[k]===top)||'warmth';const image=state.path.at(-1)?.mood||'lights';const id=[state.route.id,type,tier,motif,image].join('-');const entry={id,route:state.route.id,type,tier,motif,image};state.ending=entry;state.screen='ending';const c=collection();if(!c.includes(id)){c.push(id);try{localStorage.setItem(COLL,JSON.stringify(c))}catch{}}render()}

