function nextScene(){state.feedback=null;state.scene++;render()}
const motifs={warmth:['the warmth you offer','care that asks for nothing back','a welcome left glowing in the window'],trust:['the courage to be honest','trust built one small truth at a time','a steady hand in the dark'],spark:['the bright little spark','laughter that finds its way home','the joy of being wonderfully surprised'],honesty:['the gift of saying what is true','a door left open to the whole self','the relief of being understood']};
const images={rain:'The rain kept time on the rooftops, softening the city into a place that felt like it belonged to just the two of you.',dawn:'At dawn, the first light found every unfinished thing and made it look full of possibility.',lights:'Above you, the lanterns drifted higher—each one carrying a small brave hope into the night.'};
function ending(){const e=state.ending,r=routes.find(x=>x.id===state.route.id),name=state.profile.name;const quality={tender:'A gentle beginning',bright:'A bright kind of belonging',deep:'A light you can find your way by'};const themes=motifs[e.motif];let title,paragraph,detail;if(e.type==='romance'){title=`${quality[e.tier]} with ${r.name}`;const levels={tender:`There is a little blush in ${r.name}’s smile, and a lot of room to learn each other slowly. You don’t make grand promises. You make a plan for next week—and it feels like enough.`,bright:`You and ${r.name} walk home shoulder to shoulder, already trading ideas for the next small adventure. Whatever this becomes, you have chosen to begin it with curiosity and care.`,deep:`When ${r.name} reaches for your hand, it feels less like a finish line than a familiar path. You have built something sturdy from ${themes[e.motif]}, and there is still so much more to discover.`};paragraph=levels[e.tier];detail=`A romance shaped by ${themes[e.motif]}. Your connection is yours to define.`}else if(e.type==='friendship'){title=`The kind of friend who feels like home`;const levels={tender:`You and ${r.name} agree that friendship is not a consolation prize. It is the warm, real thing you want to make together—starting with one more late-night conversation.`,bright:`By the time you part, you have a standing invitation to ${r.name}’s world. There is no awkward almost; just a generous new friendship, full of its own possibilities.`,deep:`${r.name} becomes one of your people: the friend who shows up, tells you the truth gently, and makes the ordinary days feel a little more luminous.`};paragraph=levels[e.tier];detail=`A friendship grounded in ${themes[e.motif]}. It counts as its own happy ending.`}else{title='The beginning you give yourself';const levels={tender:`You leave the lantern festival alone, but not lonely. ${r.name} was a lovely part of the evening; the next chapter belongs to you, and you are ready to meet it as you are.`,bright:`You take the long way home, carrying the evening’s kindness with you. You have learned something about what you need, and you like the person who is learning it.`,deep:`Under the last lantern, you make a quiet promise to keep choosing a life that feels like yours. The love you are ready for begins with the person walking home: you.`};paragraph=levels[e.tier];detail=`An ending centered on ${themes[e.motif]}. Choosing yourself is a whole story.`}const epilogue=`${images[e.image]} ${paragraph} ${name}, this was one small night in a much larger life.`;const c=collection();setHeader('Your Bellwether story · ending');app.innerHTML=`<div class="panel ending-card"><div class="ending-icon">✳</div><div class="eyebrow" style="justify-content:center">Your story · ${e.type==='self'?'A life of your own':e.type==='friendship'?'A lasting friendship':'A new connection'}</div><h2 class="ending-title">${safe(title)}</h2><p class="ending-copy">${safe(epilogue)}</p><p class="ending-meta">${safe(r.name)} · ${safe(detail)}</p><div class="ending-actions">${btn('Begin again&nbsp; →','restart')}${btn('Meet someone new','cast','secondary-button')}${btn('Back to the beginning','home','secondary-button')}</div><div class="collection"><h3>Your little collection</h3><p class="panel-intro">You have found <span class="ending-count">${c.length} of 648</span> ending variations. Each story shifts with who you meet, what kind of connection you choose, what you bring forward, and how the last night feels.</p></div></div>`}
function act(action){if(action==='new-game'){state=defaults();state.screen='setup'}else if(action==='home'){state.screen='home'}else if(action==='continue'){}else if(action==='setup'){state.screen='setup'}else if(action==='cast'){state.screen='cast';state.route=null;state.feedback=null}else if(action==='next-scene'){nextScene();return}else if(action==='restart'){beginRoute(state.route.id);return}render()}
app.addEventListener('click',e=>{const target=e.target.closest('button');if(!target)return;if(target.dataset.route){beginRoute(target.dataset.route);return}if(target.dataset.choice!==undefined){choose(Number(target.dataset.choice));return}if(target.dataset.ending){finish(target.dataset.ending);return}if(target.dataset.action)act(target.dataset.action)});
document.querySelector('#home-link').addEventListener('click',e=>{e.preventDefault();act('home')});
let audio=null;document.querySelector('#sound-toggle').addEventListener('click',()=>{const button=document.querySelector('#sound-toggle');if(audio){audio.oscs.forEach(o=>{try{o.stop()}catch{}});audio.ctx.close();audio=null;button.title='Ambient sound off';button.setAttribute('aria-label','Turn ambient sound on')}else{try{const ctx=new(window.AudioContext||window.webkitAudioContext)(),gain=ctx.createGain();gain.gain.value=.012;gain.connect(ctx.destination);const oscs=[196,246.94,293.66].map((hz,i)=>{const o=ctx.createOscillator(),g=ctx.createGain();o.type='sine';o.frequency.value=hz;g.gain.value=i===0?1:.42;o.connect(g);g.connect(gain);o.start();return o});audio={ctx,oscs};button.title='Ambient sound on';button.setAttribute('aria-label','Turn ambient sound off')}catch{button.title='Sound is unavailable in this browser'}}});
render();
})();

